import type { ReactNode } from "react";

export const sidebarAppearanceValues = ["bordered", "subtle", "floating", "inset"] as const;

/** A sidebar of navigation: the team or product name at the top, grouped links with sub-items and badges, an optional footer, and the signed-in person at the bottom. It can fold down to icons, and comes in four looks. It is only the panel; DashboardShell adds the top bar and the phone menu. */
export interface SidebarSpecProps {
  /**
   * The navigation as groups of items. An item may hold one level of sub-items. An item may carry a permission ("allow", "disabled", "hidden" or { state, reason }): hidden items, and groups or parents left with nothing, are not drawn or counted; disabled items stay as focusable, non-navigating entries (aria-disabled) with the reason in a tooltip.
   */
  navigation: import("../sidebar/nav").NavGroup[];
  /**
   * The id of the page you are on. It is marked as the current page (aria-current) and its parent opens.
   */
  currentId?: string;
  /**
   * Your logo or product name at the top. Ignored when a team is given.
   */
  brand?: ReactNode;
  /**
   * The organisation or workspace shown at the top, with its logo and a second line such as the plan. Replaces brand.
   */
  team?: import("../sidebar/nav").ShellTeam;
  /**
   * Other workspaces to switch to. With two or more the team becomes a menu.
   */
  teams?: import("../sidebar/nav").ShellTeam[];
  /**
   * Called with the workspace the person chose.
   */
  onTeamChange?: (team: import("../sidebar/nav").ShellTeam) => void;
  /**
   * The signed-in person: shown at the bottom with an account menu.
   */
  user?: import("../sidebar/nav").ShellUser;
  /**
   * Content above the account area, such as an upgrade card or a storage meter. It is hidden while the sidebar is folded.
   */
  footer?: ReactNode;
  /**
   * Shows a search button under the name and calls this when it is pressed, e.g. to open a command palette.
   */
  onSearch?: () => void;
  /**
   * Text and accessible name of the search button.
   * @default "Search"
   */
  searchLabel?: string;
  /**
   * Accessible name of the navigation.
   * @default "Main navigation"
   */
  label?: string;
  /**
   * Called with the item when one is chosen. Items without an href use this to do their work.
   */
  onNavigate?: (item: import("../sidebar/nav").NavItem) => void;
  /**
   * Draw items as your router's link. Return the link with the given className and children; call onClick when chosen. Without it, items with an href are plain links.
   */
  renderLink?: (props: { item: import("../sidebar/nav").NavItem; className: string; children: import("react").ReactNode; isCurrent: boolean; onClick: () => void }) => import("react").ReactNode;
  /**
   * Called after any item is chosen. Use it to close a sheet that holds the sidebar on a phone.
   */
  onPick?: () => void;
  /**
   * Controlled: whether the sidebar is folded down to icons.
   */
  isCollapsed?: boolean;
  /**
   * Start folded down.
   * @default false
   */
  defaultCollapsed?: boolean;
  /**
   * Called when the person folds or opens the sidebar. Save it if you want it remembered.
   */
  onCollapsedChange?: (collapsed: boolean) => void;
  /**
   * Show the Collapse button at the bottom. Turn it off when you fold the sidebar from somewhere else, such as a top bar.
   * @default true
   */
  collapsible?: boolean;
  /**
   * Class names for the parts of the sidebar, by slot name, added after the built-in ones so you can restyle one part without editing the file. Slots: root, header, team-switcher, search, nav, group, item, sub-list, footer, collapse, account.
   */
  classNames?: Partial<Record<"root" | "header" | "team-switcher" | "search" | "nav" | "group" | "item" | "sub-list" | "footer" | "collapse" | "account", string>>;
  /**
   * bordered: a line on the inner edge. subtle: a tinted panel with no line. floating: a rounded raised card with a margin around it. inset: no line and no fill, for a sidebar that sits on a tinted page beside an inset page card (DashboardShell draws that page card).
   * @default "bordered"
   */
  appearance?: "bordered" | "subtle" | "floating" | "inset";
}

